 return /^body\/set\d+\/tex\d+\/mat-?\d+(?:\+vc)?\/(?:MASK|BLEND)\/paint\d+$/.test(m.name??'')&&
  p?.baseColorTexture&&equal(p.baseColorFactor,expected)&&p.metallicFactor===0;
}

